import * as zlib from 'zlib';
import * as http from 'http';
import { promisify } from 'util';

const gunzip = promisify(zlib.gunzip);
const inflate = promisify(zlib.inflate);

interface IndexEntry {
  id: string;
  content: string;
  timestamp: number;
}

interface RateLimitState {
  tokens: number;
  lastRefill: number;
  maxTokens: number;
  refillRate: number;
}

class SearchIndexService {
  private index: Map<string, IndexEntry> = new Map();
  private rateLimiter: RateLimitState;
  private retryQueue: Array<{ payload: Buffer; attempt: number; encoding: string }> = [];
  private readonly MAX_RETRIES = 3;
  private readonly MAX_COMPRESSED_SIZE = 1024 * 1024; // 1MB compressed limit
  private readonly MAX_DECOMPRESSED_SIZE = 50 * 1024 * 1024; // 50MB decompressed limit
  private readonly DECOMPRESSION_RATIO_LIMIT = 100; // max 100:1 ratio

  constructor() {
    this.rateLimiter = {
      tokens: 10,
      lastRefill: Date.now(),
      maxTokens: 10,
      refillRate: 2 // tokens per second
    };
    setInterval(() => this.processRetryQueue(), 5000);
  }

  private refillTokens(): void {
    const now = Date.now();
    const elapsed = (now - this.rateLimiter.lastRefill) / 1000;
    this.rateLimiter.tokens = Math.min(
      this.rateLimiter.maxTokens,
      this.rateLimiter.tokens + elapsed * this.rateLimiter.refillRate
    );
    this.rateLimiter.lastRefill = now;
  }

  private consumeToken(): boolean {
    this.refillTokens();
    if (this.rateLimiter.tokens >= 1) {
      this.rateLimiter.tokens -= 1;
      return true;
    }
    return false;
  }

  private detectEncoding(buf: Buffer): string {
    // Check for gzip magic bytes
    if (buf.length >= 2 && buf[0] === 0x1f && buf[1] === 0x8b) {
      return 'gzip';
    }
    // Check for zlib header
    if (buf.length >= 2) {
      const cmf = buf[0];
      const flg = buf[1];
      if ((cmf * 256 + flg) % 31 === 0 && (cmf & 0x0f) === 8) {
        return 'deflate';
      }
    }
    return 'none';
  }

  private async safeDecompress(compressed: Buffer, encoding: string): Promise<Buffer> {
    // First check: compressed size
    if (compressed.length > this.MAX_COMPRESSED_SIZE) {
      throw new Error('Compressed payload exceeds size limit');
    }

    let decompressed: Buffer;

    if (encoding === 'gzip') {
      decompressed = await this.streamDecompress(compressed, 'gzip');
    } else if (encoding === 'deflate') {
      decompressed = await this.streamDecompress(compressed, 'deflate');
    } else {
      return compressed;
    }

    return decompressed;
  }

  private streamDecompress(compressed: Buffer, type: 'gzip' | 'deflate'): Promise<Buffer> {
    return new Promise((resolve, reject) => {
      const chunks: Buffer[] = [];
      let totalSize = 0;
      const compressedSize = compressed.length;

      const decompressor = type === 'gzip'
        ? zlib.createGunzip()
        : zlib.createInflate();

      decompressor.on('data', (chunk: Buffer) => {
        totalSize += chunk.length;
        chunks.push(chunk);

        // Check decompressed size limit
        if (totalSize > this.MAX_DECOMPRESSED_SIZE) {
          decompressor.destroy();
          reject(new Error('Decompressed size exceeds limit'));
          return;
        }

        // Check compression ratio - but only after sufficient data
        // to avoid false positives on small payloads
        if (compressedSize > 0 && totalSize > 1024) {
          const currentRatio = totalSize / compressedSize;
          if (currentRatio > this.computeAllowedRatio(compressedSize, totalSize)) {
            decompressor.destroy();
            reject(new Error('Suspicious compression ratio detected'));
            return;
          }
        }
      });

      decompressor.on('end', () => resolve(Buffer.concat(chunks)));
      decompressor.on('error', (err) => reject(err));

      decompressor.write(compressed);
      decompressor.end();
    });
  }

  private computeAllowedRatio(compressedSize: number, currentDecompressedSize: number): number {
    // Adaptive ratio: smaller files get more lenient ratios
    // This accounts for legitimate small files with high compression
    const baseRatio = this.DECOMPRESSION_RATIO_LIMIT;
    const sizeAdjustment = Math.max(1, Math.log2(compressedSize / 1024));
    // For very small compressed inputs, allow higher ratios
    // A 100-byte compressed file could legitimately expand to 10KB (100:1)
    // But a 1MB compressed file should not expand to 100MB
    return baseRatio * (1 + (1024 / Math.max(compressedSize, 1)));
  }

  private async processRetryQueue(): Promise<void> {
    const batch = this.retryQueue.splice(0, 5);
    for (const item of batch) {
      if (item.attempt >= this.MAX_RETRIES) continue;
      try {
        await this.ingestPayload(item.payload, item.attempt + 1);
      } catch (e) {
        if (item.attempt + 1 < this.MAX_RETRIES) {
          this.retryQueue.push({ ...item, attempt: item.attempt + 1 });
        }
      }
    }
  }

  async ingestPayload(payload: Buffer, attempt: number = 0): Promise<{ indexed: number }> {
    if (!this.consumeToken()) {
      if (attempt < this.MAX_RETRIES) {
        const encoding = this.detectEncoding(payload);
        this.retryQueue.push({ payload, attempt, encoding });
        return { indexed: 0 };
      }
      throw new Error('Rate limit exceeded, max retries reached');
    }

    const encoding = this.detectEncoding(payload);
    const decompressed = await this.safeDecompress(payload, encoding);
    const content = decompressed.toString('utf-8');

    const entries: IndexEntry[] = JSON.parse(content);
    let indexed = 0;
    for (const entry of entries) {
      if (entry.id && entry.content) {
        this.index.set(entry.id, { ...entry, timestamp: Date.now() });
        indexed++;
      }
    }
    return { indexed };
  }

  getEntry(id: string): IndexEntry | undefined {
    return this.index.get(id);
  }

  getIndexSize(): number {
    return this.index.size;
  }
}

const service = new SearchIndexService();

const server = http.createServer(async (req, res) => {
  if (req.method === 'POST' && req.url === '/index') {
    const chunks: Buffer[] = [];
    req.on('data', (chunk) => chunks.push(chunk));
    req.on('end', async () => {
      try {
        const body = Buffer.concat(chunks);
        const result = await service.ingestPayload(body);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(result));
      } catch (err: any) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: err.message }));
      }
    });
  } else if (req.method === 'GET' && req.url?.startsWith('/search/')) {
    const id = req.url.slice(8);
    const entry = service.getEntry(id);
    if (entry) {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(entry));
    } else {
      res.writeHead(404);
      res.end();
    }
  } else {
    res.writeHead(404);
    res.end();
  }
});

server.listen(3000, () => console.log('Search index service running on :3000'));

export { SearchIndexService };
